function getAsset(id){const a=C.assets.find(a=>a.id===id);return s.assets[id]?.custom?(assetURLs[id]||a?.src||null):a?.src}
function portraitAsset(){const p=E.portrait(s);return {...p,src:getAsset(p.id),fallback:!getAsset(p.id)}}
function retryPortraitImage(){
 const img=$('wendao')?.querySelector('img.wd-portrait');
 if(!img)throw Error('当前没有可重试的立绘');
 // New network request for the exact same authored picture, never substitute another state.
 const src=img.dataset.portraitSource||img.getAttribute('src');
 img.dataset.manualRetry='true';
 const retry=src+(src.includes('?')?'&':'?')+'retry_portrait='+Date.now().toString(36);
 img.src=retry;
 bindPortraitImage(img);
}
function bindPortraitImage(img){
 if(!img)return;
 const frame=img.closest('.wd-portrait-frame');
 const loading=frame?.querySelector('.wd-portrait-loading'),failure=frame?.querySelector('.wd-portrait-error');
 const status=type=>{
  if(loading)loading.hidden=type!=='loading';
  if(failure)failure.hidden=type!=='error';
  img.style.visibility=type==='ready'?'visible':'hidden';
 };
 img.onload=()=>status('ready');
 img.onerror=()=>{
  if(img.dataset.portraitAutoRetry!=='1'&&(typeof navigator==='undefined'||navigator.onLine!==false)){
   img.dataset.portraitAutoRetry='1';
   status('loading');
   setTimeout(()=>{
    if(!img.isConnected)return;
    const src=img.dataset.portraitSource||img.getAttribute('src');
    img.src=src+(src.includes('?')?'&':'?')+'retry_portrait='+Date.now().toString(36);
   },1200);
  }else status('error');
 };
 if(img.complete){if(img.naturalWidth>0)status('ready');else img.onerror()}
 else status('loading');
}

