function portraitGalleryHTML(){return `<div class="wd-panel"><h3>温知遥 · 状态立绘</h3><p>点击看完整内置图。受伤版为完全散发、无发簪；病中版已修订。这里只预览图片，姐姐页仍按真实存档状态切换。</p><div class="wd-gallery wd-portraits">${C.assets.filter(a=>a.kind==='portrait').map(a=>`<div><button data-wd="portrait-preview" data-asset="${esc(a.id)}"><img src="${esc(a.src)}" alt="${esc(a.title)}" loading="lazy"><span>${esc(a.title)}</span></button>${s.assets[a.id]?.custom?`<p>本机自定义图覆盖中</p>${button('改用新版内置图','reset-art',`data-asset="${esc(a.id)}"`)}`:''}</div>`).join('')}</div></div>`}
