function requirement(c){const r=c.requires||{};return [r.previous?'前章完成':'',r.xp?`${r.xp}修为`:'',r.autonomy?`姐姐独立研习${r.autonomy}次`:'',r.date?`${r.date}之后`:'',r.realm?`境界${r.realm+1}`:'',r.health?`身体≥${r.health}`:'',r.pressure?`压力≥${r.pressure}`:'',r.choice?'指定剧情选择':''].filter(Boolean).join('、')}
